@echo off
rem Sample script to install the JDBC driver jar for the JDBC driver on a Windows Remote Loader server
set JAR_SOURCE=C:\downloads\sqljdbc.jar
set DEST_DIR=novell\RemoteLoader\lib
if not exist "%DEST_DIR%" (
    echo Creating destination directory %DEST_DIR%...
    mkdir "%DEST_DIR%"
)

copy "%JAR_SOURCE%" "%DEST_DIR%"
if errorlevel 1 (
    echo Failed to copy the JDBC driver jar file.
    exit /b 1
) else (
    echo JDBC driver jar file successfully copied to %DEST_DIR%.
)
